//! `radiant_vcf`: the germline and somatic SNV extractions of the Radiant ETL, in Rust (POC).
//!
//! Python entry points: `radiant_vcf.GermlineSnvReader` and `radiant_vcf.SomaticSnvReader`. See
//! `radiant/tasks/vcf/snv/rust_engine.py`.

mod consequence;
mod genotype;
mod germline;
mod hts;
mod inheritance;
mod parquet_sink;
mod snv;
mod somatic;
#[rustfmt::skip] // Generated by gen_tables.py: the staleness test compares the exact text.
mod tables;

use std::path::PathBuf;
use std::sync::Arc;

use arrow::datatypes::Schema;
use arrow::pyarrow::{FromPyArrow, ToPyArrow};
use arrow::record_batch::RecordBatch;
use pyo3::exceptions::PyRuntimeError;
use pyo3::prelude::*;
use pyo3::types::PyDict;

use germline::{Experiment, GermlineReader};
use parquet_sink::{ParquetSink, SinkConfig, WrittenFile};
use snv::Stats;
use somatic::{SomaticConfig, SomaticReader};

/// The Parquet sinks of `write_parquet`, from a dict of sink configurations keyed by table.
fn build_sinks<'py>(sinks: &Bound<'py, PyDict>) -> PyResult<Vec<(String, ParquetSink)>> {
    let mut built: Vec<(String, ParquetSink)> = Vec::new();
    for (key, conf) in sinks.iter() {
        let key: String = key.extract()?;
        let conf = conf.cast::<PyDict>()?;
        let get = |k: &str| -> PyResult<Bound<'py, PyAny>> {
            conf.get_item(k)?
                .ok_or_else(|| PyRuntimeError::new_err(format!("sink {key}: missing {k}")))
        };
        let cfg = SinkConfig {
            schema: Arc::new(Schema::from_pyarrow_bound(&get("schema")?)?),
            directory: PathBuf::from(get("directory")?.extract::<String>()?),
            prefix: get("prefix")?.extract()?,
            compression: get("compression")?.extract()?,
            compression_level: get("compression_level")?.extract()?,
            data_page_size: get("data_page_size")?.extract()?,
            dictionary_page_size: get("dictionary_page_size")?.extract()?,
            write_batch_size: get("write_batch_size")?.extract()?,
            row_group_rows: get("row_group_rows")?.extract()?,
            row_group_bytes: get("row_group_bytes")?.extract()?,
            target_file_size: get("target_file_size")?.extract()?,
        };
        built.push((key, ParquetSink::new(cfg).map_err(PyRuntimeError::new_err)?));
    }
    Ok(built)
}

/// `{table: [(local_path, record_count, size_in_bytes), ...]}`.
fn files_dict<'py>(py: Python<'py>, files: Vec<(String, Vec<WrittenFile>)>) -> PyResult<Bound<'py, PyDict>> {
    let d = PyDict::new(py);
    for (key, files) in files {
        let rows: Vec<(String, u64, u64)> = files.into_iter().map(|f| (f.path, f.rows, f.bytes)).collect();
        d.set_item(key, rows)?;
    }
    Ok(d)
}

/// `{table: pyarrow.RecordBatch}`.
fn batches_dict<'py>(py: Python<'py>, tables: &[&str], batches: Vec<RecordBatch>) -> PyResult<Bound<'py, PyDict>> {
    let d = PyDict::new(py);
    for (key, b) in tables.iter().zip(batches.iter()) {
        d.set_item(*key, b.to_pyarrow(py)?)?;
    }
    Ok(d)
}

fn stats_dict<'py>(py: Python<'py>, stats: &Stats) -> PyResult<Bound<'py, PyDict>> {
    let d = PyDict::new(py);
    d.set_item("counts", stats.counts())?;
    d.set_item("source_counts", stats.csq.source_counts.clone())?;
    d.set_item("invalid_cds", stats.csq.invalid_cds.clone())?;
    d.set_item("unknown_sources", stats.csq.unknown_sources.clone())?;
    d.set_item("malformed_comphet_examples", stats.malformed_comphet_examples.clone())?;
    Ok(d)
}

/// Reads one germline annotation VCF into the four germline SNV tables.
///
/// Args:
///     path: Local VCF/BCF path (bgzipped or not).
///     experiments: One `(aliquot, seq_id, tenant_code, family_role, affected_status, sex)` tuple per experiment.
///     task_id: Annotation task id.
///     part: Partition of the task.
///     threads: htslib decompression threads, as cyvcf2's `threads`.
#[pyclass(unsendable, module = "radiant_vcf")]
struct GermlineSnvReader {
    inner: GermlineReader,
}

#[pymethods]
impl GermlineSnvReader {
    #[new]
    #[pyo3(signature = (path, experiments, task_id, part, threads=None))]
    fn new(
        path: &str,
        experiments: Vec<(String, i32, String, String, String, String)>,
        task_id: i32,
        part: i32,
        threads: Option<usize>,
    ) -> PyResult<Self> {
        let experiments = experiments
            .into_iter()
            .map(
                |(aliquot, seq_id, tenant_code, family_role, affected_status, sex)| Experiment {
                    aliquot,
                    seq_id,
                    tenant_code,
                    family_role,
                    affected_status,
                    sex,
                },
            )
            .collect();
        let inner =
            GermlineReader::open(path, experiments, task_id, part, threads).map_err(PyRuntimeError::new_err)?;
        Ok(Self { inner })
    }

    /// The VCF samples kept, in file order.
    #[getter]
    fn samples(&self) -> Vec<String> {
        self.inner.samples.clone()
    }

    /// True when the parental origin comes from the slivar `po_*` tags.
    #[getter]
    fn slivar_parental_origin(&self) -> bool {
        self.inner.slivar_parental_origin
    }

    /// True when the transmission mode comes from the slivar mode tags.
    #[getter]
    fn slivar_transmission_mode(&self) -> bool {
        self.inner.slivar_transmission_mode
    }

    /// Reads up to `max_records` kept records. Returns a dict of `pyarrow.RecordBatch` keyed by table
    /// (`occurrence`, `variant`, `consequence`, `comphet`), or None at the end of the file.
    /// The GIL is released while the records are decoded.
    #[pyo3(signature = (max_records=10000))]
    fn next_batches<'py>(&mut self, py: Python<'py>, max_records: usize) -> PyResult<Option<Bound<'py, PyDict>>> {
        let inner = &mut self.inner;
        let batches = py
            .detach(|| inner.next_batches(max_records))
            .map_err(PyRuntimeError::new_err)?;
        batches.map(|b| batches_dict(py, &germline::TABLES, b)).transpose()
    }

    /// Reads the whole file and writes each table to Parquet files in a local directory. The GIL is released
    /// while the file is read and written.
    ///
    /// Args:
    ///     sinks: Per table key (`occurrence`, `variant`, `consequence`, `comphet`), a dict with `schema`
    ///         (`pyarrow.Schema`, the Iceberg schema without field ids), `directory`, `prefix`, `compression`,
    ///         `compression_level`, `data_page_size`, `dictionary_page_size`, `write_batch_size`,
    ///         `row_group_rows`, `row_group_bytes`, `target_file_size`.
    ///     batch_records: Records decoded between two writes.
    ///
    /// Returns:
    ///     Per table key, the files written as `(local_path, record_count, size_in_bytes)`.
    #[pyo3(signature = (sinks, batch_records=10000))]
    fn write_parquet<'py>(
        &mut self,
        py: Python<'py>,
        sinks: &Bound<'py, PyDict>,
        batch_records: usize,
    ) -> PyResult<Bound<'py, PyDict>> {
        let mut built = build_sinks(sinks)?;
        let inner = &mut self.inner;
        let files = py
            .detach(|| inner.write_parquet(&mut built, batch_records))
            .map_err(PyRuntimeError::new_err)?;
        files_dict(py, files)
    }

    /// Counters for the end-of-file logs: `counts`, `source_counts`, `invalid_cds`, `unknown_sources`,
    /// `malformed_comphet_examples`.
    fn stats<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyDict>> {
        stats_dict(py, &self.inner.stats)
    }
}

/// Reads one somatic annotation VCF into `somatic_snv_occurrence`, `snv_variant` and `snv_consequence`.
///
/// Opening never fails on the samples: check `file_samples` and `samples` first (as `process_task` does), then call
/// `configure` with the tumor and normal samples.
///
/// Args:
///     path: Local VCF/BCF path (bgzipped or not).
///     aliquots: The task's aliquots, selected as cyvcf2's `set_samples` does.
///     task_id: Annotation task id.
///     part: Partition of the task.
///     threads: htslib decompression threads, as cyvcf2's `threads`.
#[pyclass(unsendable, module = "radiant_vcf")]
struct SomaticSnvReader {
    inner: SomaticReader,
}

#[pymethods]
impl SomaticSnvReader {
    #[new]
    #[pyo3(signature = (path, aliquots, task_id, part, threads=None))]
    fn new(path: &str, aliquots: Vec<String>, task_id: i32, part: i32, threads: Option<usize>) -> PyResult<Self> {
        let inner = SomaticReader::open(path, &aliquots, task_id, part, threads).map_err(PyRuntimeError::new_err)?;
        Ok(Self { inner })
    }

    /// The samples of the file, before the aliquots are selected.
    #[getter]
    fn file_samples(&self) -> Vec<String> {
        self.inner.file_samples.clone()
    }

    /// The samples kept, in file order.
    #[getter]
    fn samples(&self) -> Vec<String> {
        self.inner.samples.clone()
    }

    /// Sets the tumor and normal samples (indexes into `samples`). `normal_index` and `normal_seq_id` are None for
    /// a tumor-only analysis. Raises when the header has no CSQ line.
    #[pyo3(signature = (tumor_index, tumor_seq_id, tenant_code, normal_index=None, normal_seq_id=None))]
    fn configure(
        &mut self,
        tumor_index: usize,
        tumor_seq_id: i32,
        tenant_code: String,
        normal_index: Option<usize>,
        normal_seq_id: Option<i32>,
    ) -> PyResult<()> {
        self.inner
            .configure(SomaticConfig {
                tumor_index,
                normal_index,
                tumor_seq_id,
                tenant_code,
                normal_seq_id,
            })
            .map_err(PyRuntimeError::new_err)
    }

    /// As `GermlineSnvReader.next_batches`, for the tables `occurrence`, `variant`, `consequence`.
    #[pyo3(signature = (max_records=10000))]
    fn next_batches<'py>(&mut self, py: Python<'py>, max_records: usize) -> PyResult<Option<Bound<'py, PyDict>>> {
        let inner = &mut self.inner;
        let batches = py
            .detach(|| inner.next_batches(max_records))
            .map_err(PyRuntimeError::new_err)?;
        batches.map(|b| batches_dict(py, &somatic::TABLES, b)).transpose()
    }

    /// As `GermlineSnvReader.write_parquet`, for the tables `occurrence`, `variant`, `consequence`.
    #[pyo3(signature = (sinks, batch_records=10000))]
    fn write_parquet<'py>(
        &mut self,
        py: Python<'py>,
        sinks: &Bound<'py, PyDict>,
        batch_records: usize,
    ) -> PyResult<Bound<'py, PyDict>> {
        let mut built = build_sinks(sinks)?;
        let inner = &mut self.inner;
        let files = py
            .detach(|| inner.write_parquet(&mut built, batch_records))
            .map_err(PyRuntimeError::new_err)?;
        files_dict(py, files)
    }

    /// As `GermlineSnvReader.stats`.
    fn stats<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyDict>> {
        stats_dict(py, &self.inner.stats)
    }
}

/// `snv/common.py::locus_and_hash`, exposed for tests.
#[pyfunction]
fn locus_and_hash(chrom: &str, pos: i64, reference: &str, alternate: &str) -> (String, String) {
    snv::locus_and_hash(chrom, pos, reference, alternate)
}

#[pymodule]
fn radiant_vcf(m: &Bound<'_, PyModule>) -> PyResult<()> {
    m.add_class::<GermlineSnvReader>()?;
    m.add_class::<SomaticSnvReader>()?;
    m.add_function(wrap_pyfunction!(locus_and_hash, m)?)?;
    Ok(())
}
